use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < T : Idx > DenseBitSet < T > { # [doc = " Creates a new, empty bitset with a given `domain_size`."] # [inline] pub fn new_empty (domain_size : usize) -> DenseBitSet < T > { let num_words = num_words (domain_size) ; DenseBitSet { domain_size , words : smallvec ! [0 ; num_words] , marker : PhantomData } } # [doc = " Creates a new, filled bitset with a given `domain_size`."] # [inline] pub fn new_filled (domain_size : usize) -> DenseBitSet < T > { let num_words = num_words (domain_size) ; let mut result = DenseBitSet { domain_size , words : smallvec ! [! 0 ; num_words] , marker : PhantomData } ; result . clear_excess_bits () ; result } # [doc = " Clear all elements."] # [inline] pub fn clear (& mut self) { self . words . fill (0) ; } # [doc = " Clear excess bits in the final word."] fn clear_excess_bits (& mut self) { clear_excess_bits_in_final_word (self . domain_size , & mut self . words) ; } # [doc = " Count the number of set bits in the set."] pub fn count (& self) -> usize { self . words . iter () . map (| e | e . count_ones () as usize) . sum () } # [doc = " Returns `true` if `self` contains `elem`."] # [inline] pub fn contains (& self , elem : T) -> bool { assert ! (elem . index () < self . domain_size) ; let (word_index , mask) = word_index_and_mask (elem) ; (self . words [word_index] & mask) != 0 } # [doc = " Is `self` is a (non-strict) superset of `other`?"] # [inline] pub fn superset (& self , other : & DenseBitSet < T >) -> bool { assert_eq ! (self . domain_size , other . domain_size) ; self . words . iter () . zip (& other . words) . all (| (a , b) | (a & b) == * b) } # [doc = " Is the set empty?"] # [inline] pub fn is_empty (& self) -> bool { self . words . iter () . all (| a | * a == 0) } # [doc = " Insert `elem`. Returns whether the set has changed."] # [inline] pub fn insert (& mut self , elem : T) -> bool { assert ! (elem . index () < self . domain_size , "inserting element at index {} but domain size is {}" , elem . index () , self . domain_size ,) ; let (word_index , mask) = word_index_and_mask (elem) ; let word_ref = & mut self . words [word_index] ; let word = * word_ref ; let new_word = word | mask ; * word_ref = new_word ; new_word != word } # [inline] pub fn insert_range (& mut self , elems : impl RangeBounds < T >) { let Some ((start , end)) = inclusive_start_end (elems , self . domain_size) else { return ; } ; let (start_word_index , start_mask) = word_index_and_mask (start) ; let (end_word_index , end_mask) = word_index_and_mask (end) ; for word_index in (start_word_index + 1) .. end_word_index { self . words [word_index] = ! 0 ; } if start_word_index != end_word_index { self . words [start_word_index] |= ! (start_mask - 1) ; self . words [end_word_index] |= end_mask | (end_mask - 1) ; } else { self . words [start_word_index] |= end_mask | (end_mask - start_mask) ; } } # [doc = " Sets all bits to true."] pub fn insert_all (& mut self) { self . words . fill (! 0) ; self . clear_excess_bits () ; } # [doc = " Checks whether any bit in the given range is a 1."] # [inline] pub fn contains_any (& self , elems : impl RangeBounds < T >) -> bool { let Some ((start , end)) = inclusive_start_end (elems , self . domain_size) else { return false ; } ; let (start_word_index , start_mask) = word_index_and_mask (start) ; let (end_word_index , end_mask) = word_index_and_mask (end) ; if start_word_index == end_word_index { self . words [start_word_index] & (end_mask | (end_mask - start_mask)) != 0 } else { if self . words [start_word_index] & ! (start_mask - 1) != 0 { return true ; } let remaining = start_word_index + 1 .. end_word_index ; if remaining . start <= remaining . end { self . words [remaining] . iter () . any (| & w | w != 0) || self . words [end_word_index] & (end_mask | (end_mask - 1)) != 0 } else { false } } } # [doc = " Returns `true` if the set has changed."] # [inline] pub fn remove (& mut self , elem : T) -> bool { assert ! (elem . index () < self . domain_size) ; let (word_index , mask) = word_index_and_mask (elem) ; let word_ref = & mut self . words [word_index] ; let word = * word_ref ; let new_word = word & ! mask ; * word_ref = new_word ; new_word != word } # [doc = " Iterates over the indices of set bits in a sorted order."] # [inline] pub fn iter (& self) -> BitIter < '_ , T > { BitIter :: new (& self . words) } pub fn last_set_in (& self , range : impl RangeBounds < T >) -> Option < T > { let (start , end) = inclusive_start_end (range , self . domain_size) ? ; let (start_word_index , _) = word_index_and_mask (start) ; let (end_word_index , end_mask) = word_index_and_mask (end) ; let end_word = self . words [end_word_index] & (end_mask | (end_mask - 1)) ; if end_word != 0 { let pos = max_bit (end_word) + WORD_BITS * end_word_index ; if start <= pos { return Some (T :: new (pos)) ; } } if let Some (offset) = self . words [start_word_index .. end_word_index] . iter () . rposition (| & w | w != 0) { let word_idx = start_word_index + offset ; let start_word = self . words [word_idx] ; let pos = max_bit (start_word) + WORD_BITS * word_idx ; if start <= pos { return Some (T :: new (pos)) ; } } None } bit_relations_inherent_impls ! { } # [doc = " Sets `self = self | !other`."] # [doc = ""] # [doc = " FIXME: Incorporate this into [`BitRelations`] and fill out"] # [doc = " implementations for other bitset types, if needed."] pub fn union_not (& mut self , other : & DenseBitSet < T >) { assert_eq ! (self . domain_size , other . domain_size) ; bitwise (& mut self . words , & other . words , | a , b | a | ! b) ; self . clear_excess_bits () ; } }
}